def get_salary_accounting_dataframe():
    """获取薪酬核算基础数据DataFrame"""
    return pd.DataFrame(SALARY_ACCOUNTING_DATA)

def filter_by_category(category):
    """根据类别筛选数据（如果有类别字段）"""
    df = get_salary_accounting_dataframe()
    if df.empty:
        return df
    if '类别' in df.columns:
        return df[df['类别'] == category]
    return df

def get_all_categories():
    """获取所有类别列表（如果有类别字段）"""
    df = get_salary_accounting_dataframe()
    if df.empty:
        return []
    if '类别' in df.columns:
        return df['类别'].unique().tolist()
    return []

def get_category_stats():
    """获取类别统计信息（如果有类别字段）"""
    df = get_salary_accounting_dataframe()
    if df.empty:
        return {}
    if '类别' in df.columns:
        return df['类别'].value_counts().to_dict()
    return {}

def get_salary_accounting_by_id(record_id):
    """根据记录ID获取薪酬核算基础数据"""
    df = get_salary_accounting_dataframe()
    if df.empty:
        return None
    if len(df) > 0:
        first_col = df.columns[0]
        if 'ID' in first_col.upper() or '代码' in first_col or '编号' in first_col:
            result = df[df[first_col].astype(str) == str(record_id)]
        else:
            try:
                idx = int(record_id)
                if 0 <= idx < len(df):
                    result = df.iloc[[idx]]
                else:
                    return None
            except (ValueError, TypeError):
                return None
        
        if len(result) > 0:
            return result.iloc[0].to_dict()
    return None
